import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/stats/variants/06-cards";
export interface ArtemisStatsCardsProps { className?: string;  }
export function ArtemisStatsCards({className}:ArtemisStatsCardsProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
import { NumberTicker } from "./06-cards/number-ticker";
const HEADER_VIEWPORT = { once: true, amount: 0.39 } as const;
const CARD_VIEWPORT = { once: true, amount: 0.185 } as const;
const HEADER_HIDDEN = { opacity: 0, y: 14 };
const CARD_HIDDEN = { opacity: 0, scale: 0.985, y: 18 };
const SHOWN = { opacity: 1, scale: 1, y: 0 };
const CARD_STAGGER_S = 0.06;
const STATS = [
    {
        title: "Workflows completed",
        delta: "32%",
        value: "28",
        suffix: "k+",
        body: "Approved work moved from brief to live this month.",
    },
    {
        title: "Active workspaces",
        delta: "18%",
        value: "4,200",
        suffix: "",
        body: "Teams with at least one shared workflow in the last 30 days.",
    },
    {
        title: "On-time delivery",
        delta: "4%",
        value: "99",
        suffix: "%",
        body: "Projects completed on or ahead of their planned launch date.",
    },
];
export default function StatsCards() {
    const reduce = useReducedMotion();
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:text-foreground">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <motion.header className="art:max-w-3xl" initial={HEADER_HIDDEN} whileInView={reduce ? undefined : { opacity: 1, y: 0 }} viewport={HEADER_VIEWPORT} transition={ARTEMIS_SPRING_PANEL}>
              <p className="art:font-medium art:text-muted-foreground art:text-sm">
                {"Performance brief"}
              </p>
              <h2 className="art:mt-4 art:text-balance art:font-medium art:text-4xl art:leading-tight art:tracking-tight">
                {"The numbers behind the work."}
              </h2>
              <p className="art:mt-5 art:max-w-2xl art:text-pretty art:text-muted-foreground art:leading-7">
                {"A rolling view of delivery, adoption, and the pace teams sustain after launch."}
              </p>
            </motion.header>
            <div className="art:mt-9 art:grid art:gap-4 art:@min-[768px]/artemis:grid-cols-3">
              {STATS.map((stat, i) => (<motion.article key={stat.title} className="art:rounded-2xl art:bg-background art:p-2" initial={CARD_HIDDEN} whileInView={reduce ? undefined : SHOWN} viewport={CARD_VIEWPORT} transition={{ ...ARTEMIS_SPRING_LAYOUT, delay: i * CARD_STAGGER_S }}>
                  <div className="art:flex art:min-h-12 art:items-center art:justify-between art:gap-4 art:px-2 art:py-1">
                    <h3 className="art:text-balance art:font-medium art:text-xl art:leading-tight art:tracking-tight">
                      {stat.title}
                    </h3>
                    <span className="art:inline-flex art:shrink-0 art:items-center art:gap-1 art:rounded-full art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-foreground art:text-xs">
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5" aria-hidden="true">
                        <path d="M7 7h10v10"/>
                        <path d="M7 17 17 7"/>
                      </svg>
                      <span className="art:sr-only">
                        {"Increased"}
                        {" by"}
                      </span>
                      {stat.delta}
                    </span>
                  </div>
                  <div className="art:flex art:min-h-56 art:flex-col art:rounded-2xl art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
                    <p className="art:font-medium art:text-5xl art:tabular-nums art:tracking-tighter art:@min-[640px]/artemis:text-6xl">
                      <NumberTicker text={stat.value} suffix={stat.suffix}/>
                    </p>
                    <div className="art:mt-auto art:border-border art:border-t art:pt-5">
                      <p className="art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
                        {stat.body}
                      </p>
                    </div>
                  </div>
                </motion.article>))}
            </div>
          </div>
        </section>
      </div>
    </>);
}

"use client";
// @zeus-internal
import { ArtemisRollingNumber } from "../../../../lib/rolling-number";
export interface NumberTickerProps { text: string; className?: string; duration?: number; stagger?: number; prefix?: string; suffix?: string; label?: string; entrance?: boolean; }
export function NumberTicker({ text, className, duration = 0.9, stagger = 0.04, prefix, suffix, label }: NumberTickerProps) { return <ArtemisRollingNumber text={text} className={className} duration={duration} stagger={stagger} prefix={prefix} suffix={suffix} label={label} activation={"in-view"} amount={0.6}/>; }

"use client";
// @zeus-internal
import { animate, motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisRollingNumberProps {
  text: string;
  duration?: number;
  stagger?: number;
  className?: string;
  reducedMotion?: boolean;
  blur?: boolean;
  activation?: "in-view" | "immediate" | "mount";
  amount?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  blurUpdatesOnly?: boolean;
  staggerDigitsOnly?: boolean;
}
function Wheel({ value, delay, duration, reduced, blur, fromZero, blurUpdatesOnly }: { value: string; delay: number; duration: number; reduced: boolean; blur: boolean; fromZero: boolean; blurUpdatesOnly: boolean }) {
  const rail = useRef<HTMLSpanElement>(null);
  const firstPaint = useRef(true);
  useEffect(() => {
    const initial = firstPaint.current;
    firstPaint.current = false;
    if (!rail.current) return;
    if (!blur || reduced || value === "0" && !blurUpdatesOnly) { rail.current.style.filter = "none"; return; }
    if (blurUpdatesOnly && initial) return;
    const playback = animate(rail.current, { filter: ["blur(10px)", "blur(0px)"] }, { duration: 0.32, delay, ease: ARTEMIS_EASE_OUT });
    return () => playback.stop();
  }, [value, blur, reduced, blurUpdatesOnly]);
  return <span className="art:relative art:inline-block" style={{ clipPath: "inset(0)", lineHeight: "1.1em", height: "1.1em", width: "1ch", textAlign: "center" }}>
    <span className="art:invisible">{value}</span>
    <motion.span ref={rail} className="art:absolute art:inset-x-0 art:top-0 art:flex art:flex-col art:items-center art:will-change-[transform,filter]" initial={fromZero && !reduced ? { y: 0 } : false} animate={{ y: `${-Number(value) * 11 / 10}em` }} transition={reduced ? { duration: 0 } : { duration, delay, ease: ARTEMIS_EASE_OUT }}>
      {Array.from({ length: 10 }, (_, digit) => <span key={digit} className="art:flex art:items-center art:justify-center art:leading-none" style={{ height: "1.1em" }}>{digit}</span>)}
    </motion.span>
  </span>;
}
export function ArtemisRollingNumber({ text, duration = 0.6, stagger = 0.02, className = "", reducedMotion, blur = false, activation = "in-view", amount = 0.6, prefix = "", suffix = "", label, blurUpdatesOnly = false, staggerDigitsOnly = false }: ArtemisRollingNumberProps) {
  const anchor = useRef<HTMLSpanElement>(null);
  const observed = useInView(anchor, { once: true, amount });
  const visible = activation !== "in-view" || observed;
  const preference = useReducedMotion() === true;
  const reduced = reducedMotion ?? preference;
  const [settled, setSettled] = useState(false);
  const firstText = useRef(text), changedSinceMount = useRef(false);
  if (text !== firstText.current) changedSinceMount.current = true;
  useEffect(() => {
    if (!visible || settled) return;
    const timer = setTimeout(() => setSettled(true), (duration + text.length * stagger) * 1000);
    return () => clearTimeout(timer);
  }, [visible, settled, duration, stagger, text.length]);
  return <span ref={anchor} className={`art:inline-flex art:items-baseline art:tabular-nums ${className}`}>
    <span className="art:sr-only">{label ?? prefix + text + suffix}</span>
    <span aria-hidden="true" className="art:inline-flex art:items-baseline">{prefix && <span>{prefix}</span>}{Array.from(text, (char, index) => /[0-9]/.test(char)
      ? <Wheel key={text.length - index} value={visible || reduced ? char : "0"} delay={settled || reduced || activation === "mount" && changedSinceMount.current ? 0 : (staggerDigitsOnly ? text.slice(0, index).replace(/\D/g, "").length : index) * stagger} duration={duration} reduced={reduced} blur={blur} fromZero={activation === "mount"} blurUpdatesOnly={blurUpdatesOnly}/>
      : <span key={text.length - index}>{char}</span>)}{suffix && <span>{suffix}</span>}</span>
  </span>;
}
